/* Photo textures (CC0, Poly Haven), downloaded and re-encoded through Blender. */
const RA_TEX={"asphalt": "data:image/jpeg;base64,", "brick": "data:image/jpeg;base64,", "carpet": "data:image/jpeg;base64,", "concrete": "data:image/jpeg;base64,", "facade": "data:image/jpeg;base64,", "grass": "data:image/jpeg;base64,", "lane": "data:image/jpeg;base64,", "paving": "data:image/jpeg;base64,", "plaster": "data:image/jpeg;base64,", "roofflat": "data:image/jpeg;base64,", "sand": "data:image/jpeg;base64,", "shingle": "data:image/jpeg;base64,", "siding": "data:image/jpeg;base64,", "stone": "data:image/jpeg;base64,", "tile": "data:image/jpeg;base64,", "wood": "data:image/jpeg;base64,"};

// key: [repeat multiplier, canvas filter, multiply colour or null, source]
const TEX_SPEC={grass:[2.5,'brightness(1.08) saturate(1.5) hue-rotate(12deg)',null],asphalt:[2,'brightness(1.05)',null],paving:[1.5,'brightness(1.15) saturate(.7)',null],
 concrete:[1,'brightness(1.25)',null],sand:[2,'brightness(1.25) saturate(1.15) sepia(.25)',null],wood:[2,'brightness(1.08)',null],tile:[2,'brightness(1.12)',null],
 carpet:[2,'brightness(2.1) saturate(.8)',null],stone:[1,'brightness(1.6)',null],facade:[1,'brightness(1.5) saturate(.55)',null],siding:[1.5,'brightness(1.25) saturate(.6)',null],
 brick:[2,'none',null],plaster:[1,'brightness(1.15)',null],shingle:[1.5,'brightness(1.05)',null],roofflat:[1,'brightness(1.1)',null],lane:[2,'brightness(1.1)','tile']};
function loadPhotoTextures(){const maxA=ren.capabilities.getMaxAnisotropy?ren.capabilities.getMaxAnisotropy():1;
 Object.entries(TEX_SPEC).forEach(([key,[mul,filter,src]])=>{const url=RA_TEX[src||key];if(!url)return;const img=new Image();
  img.onload=()=>{let out=img;try{const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const g=c.getContext('2d');if(filter&&filter!=='none')g.filter=filter;g.drawImage(img,0,0);out=c;}catch(e){}
   const seen=new Set();scene.traverse(o=>{if(!o.isMesh)return;(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>{const t=m&&m.map;if(!t||t.name!==key||seen.has(t))return;seen.add(t);
    t.image=out;t.repeat.multiplyScalar(mul);t.anisotropy=maxA;t.needsUpdate=true;if(key==='grass'||key==='sand'||key==='asphalt')m.color&&m.color.offsetHSL(0,0,0);});});
   TX[key].image=out;TX[key].needsUpdate=true;};img.src=url;});}
loadPhotoTextures();
